/** @file
 * A file of debug printing stuff for conversation-related things,
 * although really anything can use this so long as it includes this
 * header file and defines DEBUG_CONVERSATION in conversation.c
 *
 * define DEBUG_CONVERSATION before including this file to turn on printing
 * and also define it in conversation.c (because it has the indent variable)
 *
 * By Hadriel Kaplan <hadrielk at yahoo dot com>
 * Copyright 2014 Hadriel Kaplan
 *
 * SPDX-License-Identifier: GPL-2.0-or-later
 */

#ifndef _CONVERSATION_DEBUG_H
#define _CONVERSATION_DEBUG_H

#ifdef DEBUG_CONVERSATION

#include <stdio.h>

extern int _debug_conversation_indent; /* the instance is in conversation.c */

#define DINDENT() _debug_conversation_indent += 4
#define DENDENT() _debug_conversation_indent -= 4

#define DPRINT(arg) \
    g_printerr("%*.*s%s: ", \
            _debug_conversation_indent,_debug_conversation_indent," ", \
            G_STRLOC); \
g_printerr arg; \
g_printerr("\n")

#define DPRINT2(arg) \
    g_printerr("%*.*s", \
            _debug_conversation_indent,_debug_conversation_indent," "); \
    g_printerr arg; \
    g_printerr("\n")

#define DINSTR(arg) arg

#else /* !DEBUG_CONVERSATION */

/* a hack to let these defines be used with trailing semi-colon and not
 * cause gcc extra-check pedantic warnings for extra colons
 */
#define DINDENT() (void)0
#define DENDENT() (void)0
#define DPRINT(arg) (void)0
#define DPRINT2(arg) (void)0
#define DINSTR(arg) (void)0

#endif /* DEBUG_CONVERSATION */

#endif /* _CONVERSATION_DEBUG_H */
/* End embedded header */

/* Begin epan/conv_id.h */
/** @file
 *
 * conv_id   2011 Robert Bullen
 *
 * Wireshark - Network traffic analyzer
 * By Gerald Combs <gerald@wireshark.org>
 * Copyright 1998 Gerald Combs
 *
 * SPDX-License-Identifier: GPL-2.0-or-later
 */

#ifndef __CONV_ID_H__
#define __CONV_ID_H__

/** conv_id_t is a type that can aid in conversation identification. When
 *  included in a "conversation key", whatever that may be, in addition to the
 *  typical { address, port, address, port } quadruple, it helps differentiate
 *  in case the quadruple is not sufficiently unique. For example, it is not
 *  uncommon to see a TCP quadruple reused these days, and employing a
 *  conv_id_t field ensures that each instance of a reused TCP conversation is
 *  tracked independently. Currently this type is used in both Wireshark's and
 *  tshark's conversation tables implementations (they are different, hence
 *  the need for a whole header file for this one silly type alias).
 *
 *  The "protocol" or "statistic" code responsible for instantiating the
 *  "conversation key" is also responsible for assigning its conv_id_t, and
 *  therefore its interpretation is specific to its assignor. For example, the
 *  TCP conversations tables in Wireshark and tshark assign the value of
 *  tcp.stream. If a conv_id_t field is not used, it should be assigned the
 *  value CONV_ID_UNSET.
 */
typedef guint32 conv_id_t;
#define CONV_ID_UNSET G_MAXUINT32

#endif /* __CONV_ID_H__ */
